import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { createServer } from 'vite';

// Server-render « Données & méthode » (`/datasets`) through Vite SSR, without a listening server:
// the page's own load runs on the served answer of `GET /v1/datasets` (the fixture generated by
// the backend and pinned to its catalogue), then the page component is rendered. The rent-control
// card must carry the « Non qualifié » badge and the served reason of its quarantine, with none of
// the fabricated rent or geographic attribution of the former detail page (COR-09/13/15, D-40).
const REPONSE = JSON.parse(
  readFileSync(new URL('../src/lib/data/__fixtures__/datasets-api.json', import.meta.url), 'utf8')
);

const server = await createServer({
  server: { middlewareMode: true },
  resolve: { preserveSymlinks: true }
});
try {
  const { load } = await server.ssrLoadModule('/src/routes/(marketing)/datasets/+page.ts');
  const { default: Page } = await server.ssrLoadModule('/src/routes/(marketing)/datasets/+page.svelte');
  const { render } = await server.ssrLoadModule('svelte/server');
  const requests = [];
  const fetchStub = async (input) => {
    requests.push(new URL(String(input)).pathname);
    return new Response(JSON.stringify(REPONSE), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  };
  const data = await load({ fetch: fetchStub });
  assert.deepEqual(requests, ['/v1/datasets']);
  assert.equal(data.panne, false);
  const { body, head } = render(Page, { props: { data } });

  const encadrement = REPONSE.donnees.find((jeu) => jeu.nom === 'encadrement_loyers');
  assert.equal(encadrement.statut, 'quarantined');
  const carte = /<article id="encadrement_loyers"[\s\S]*?<\/article>/.exec(body)?.[0];
  assert.ok(carte, 'the encadrement_loyers card is rendered');
  assert.match(carte, /Non qualifié/);
  assert.ok(carte.includes(encadrement.quarantaine), 'served reason rendered verbatim');
  assert.match(carte, /HTTP 503/);
  assert.match(carte, /ne signifie pas absence/);
  assert.match(carte, /sélection manuelle/);
  assert.doesNotMatch(body, /Graslin|loyer_reference_majore|paginées par curseur/);
  const html = '<!doctype html><html lang="fr"><head>' + head + '</head><body>' + body + '</body></html>';
  if (process.argv[2]) writeFileSync(process.argv[2], html, 'utf8');
  console.log(JSON.stringify({ status: 'passed', renderer: 'Svelte server /datasets page on the served /v1/datasets answer', sha256: createHash('sha256').update(html).digest('hex') }));
} finally {
  await server.close();
}
